//go:build loong64

package floats

// LASX Maximum and Minimum kernels (maxmin.go, gated on hasLASX, lanes_loong64.go),
// generated by go-asmgen (maxmin_loong64_gen.go) into maxmin_loong64.s. A kernel
// does the whole blocks of eight elements; the Go code finishes the last seven
// with the scalar rule.
//
//go:noescape
func maximumLASX(dst, a, b *float64, n int)

//go:noescape
func minimumLASX(dst, a, b *float64, n int)

func vmaximum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n == 0 || !hasLASX {
		maximumRef(dst, a, b)
		return
	}
	maximumLASX(&dst[0], &a[0], &b[0], n)
	maximumRef(dst[n:], a[n:], b[n:])
}

func vminimum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n == 0 || !hasLASX {
		minimumRef(dst, a, b)
		return
	}
	minimumLASX(&dst[0], &a[0], &b[0], n)
	minimumRef(dst[n:], a[n:], b[n:])
}
